package com.simibubi.create.content.legacy;

import static com.simibubi.create.content.legacy.LegacyMaterialGameTests.*;
import com.simibubi.create.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Blocks;

/** Proposed finite-custody tests through genuine native failure/save boundaries. Runtime UNRUN. */
public final class LegacyMaterialDeliveryGameTests {
 @GameTest public void pinnedPostSplitAliasResetsChargedSingletonButIncrementsOverstackedRemainder(GameTestHelper h){var pos=h.absolutePos(LIGHT);h.getLevel().setBlockAndUpdate(pos,Blocks.GLOWSTONE.defaultBlockState());var singleton=source(h,1,4);var old=singleton.getItem();h.assertTrue(AllItems.CHROMATIC_COMPOUND.checkLight(old,singleton,h.getLevel(),old,singleton.position(),pos,h.getLevel().getBlockState(pos))&&singleton.isRemoved(),"Actual pinned-source singleton is split before same-alias component read");h.assertTrue(nearby(h,AllItems.CHROMATIC_COMPOUND).stream().filter(entity->AllItems.CHROMATIC_COMPOUND.getLight(entity.getItem())==1).count()==1,"Official1.21.1 empty getter dispatch returns0 after last split: source output deliberately resets to1");h.getLevel().setBlockAndUpdate(pos,Blocks.GLOWSTONE.defaultBlockState());var overstacked=source(h,2,4);var actual=overstacked.getItem();h.assertTrue(AllItems.CHROMATIC_COMPOUND.checkLight(actual,overstacked,h.getLevel(),actual,overstacked.position(),pos,h.getLevel().getBlockState(pos))&&actual.getCount()==1&&AllItems.CHROMATIC_COMPOUND.getLight(actual)==4&&nearby(h,AllItems.CHROMATIC_COMPOUND).stream().filter(entity->AllItems.CHROMATIC_COMPOUND.getLight(entity.getItem())==5).count()==1,"Old overstacked input remains nonempty after split, so source same-alias read increments existing4 to5");h.succeed();}
 @GameTest public void refusedRadianceKeepsPaidPlainResultAndExactOriginalEndpoint(GameTestHelper h){var source=source(h,3,10);var observation=new LegacyMaterialTestFixtures.Observation();LegacyMaterialTestFixtures.with(h.getLevel(),source,null,LegacyMaterialTestFixtures.Mode.REFUSE,observation,source::tick);var actual=observation.endpoint;h.assertTrue(source.getItem().getCount()==2&&!source.getItem().has(AllDataComponents.CHROMATIC_COMPOUND_COLLECTING_LIGHT)&&observation.attempts==1&&actual.getItem().is(AllItems.REFINED_RADIANCE)&&h.getLevel().getEntity(actual.getUUID())==null&&LegacyMaterialTestFixtures.owned(h.getLevel(),AllItems.REFINED_RADIANCE)==1,"Actual native refusal leaves debited source and one durable plain result at exact prospective identity");LegacyMaterialTestFixtures.retry(h.getLevel());h.assertTrue(h.getLevel().getEntity(actual.getUUID())==actual&&LegacyMaterialTestFixtures.owned(h.getLevel(),AllItems.REFINED_RADIANCE)==0,"Retry admits original actual native endpoint once");h.succeed();}
 @GameTest public void savedRefusedRadianceDecodesNativeFlagsAndEmitsOnce(GameTestHelper h){var source=source(h,1,10);var observation=new LegacyMaterialTestFixtures.Observation();LegacyMaterialTestFixtures.with(h.getLevel(),source,null,LegacyMaterialTestFixtures.Mode.REFUSE,observation,source::tick);var uuid=observation.endpoint.getUUID();var saved=LegacyMaterialTestFixtures.capture(h.getLevel());LegacyMaterialTestFixtures.decode(h.getLevel(),saved);LegacyMaterialTestFixtures.retry(h.getLevel());var admitted=(net.minecraft.world.entity.item.ItemEntity)h.getLevel().getEntity(uuid);h.assertTrue(source.isRemoved()&&admitted!=null&&LegacyItemData.of(admitted).getBooleanOr("JustCreated",false)&&LegacyMaterialTestFixtures.owned(h.getLevel(),AllItems.REFINED_RADIANCE)==0,"Native codec restores paid result/UUID and actual JustCreated state without restoring consumed source");admitted.tick();h.assertTrue(admitted.isNoGravity()&&admitted.isSilent()&&!LegacyItemData.of(admitted).contains("JustCreated"),"Decoded actual Radiance executes source first-tick effect");h.succeed();}
 @GameTest public void removedRejectedEndpointTransfersOnlyCurrentMutatedCargo(GameTestHelper h){var source=source(h,1,10);var observation=new LegacyMaterialTestFixtures.Observation();LegacyMaterialTestFixtures.with(h.getLevel(),source,null,LegacyMaterialTestFixtures.Mode.MUTATE_REMOVE_REFUSE,observation,source::tick);h.assertTrue(source.isRemoved()&&observation.endpoint.isRemoved()&&LegacyMaterialTestFixtures.owned(h.getLevel(),AllItems.REFINED_RADIANCE)==0&&LegacyMaterialTestFixtures.owned(h.getLevel(),Items.EMERALD)==3,"Removed unadmitted native endpoint preserves only actual current replacement cargo, with no old Radiance resurrection");LegacyMaterialTestFixtures.retry(h.getLevel());h.assertTrue(nearby(h,Items.EMERALD).stream().mapToInt(entity->entity.getItem().getCount()).sum()==3&&h.getLevel().getEntity(observation.endpoint.getUUID())==null&&LegacyMaterialTestFixtures.owned(h.getLevel(),Items.EMERALD)==0,"Fresh native factory handles current loose cargo without reviving terminal endpoint");h.succeed();}
 @GameTest public void earlyNativeSaveSeesRetiredReceiptBeforeVisibilityAndNoSecondSourcePayment(GameTestHelper h){var source=source(h,3,10);var observation=new LegacyMaterialTestFixtures.Observation();LegacyMaterialTestFixtures.with(h.getLevel(),source,null,LegacyMaterialTestFixtures.Mode.EARLY_REENTER,observation,source::tick);h.assertTrue(observation.exactInsertion&&observation.notYetVisible&&observation.saved.getListOrEmpty("Pending").isEmpty()&&source.getItem().getCount()==2&&nearby(h,AllItems.REFINED_RADIANCE).size()==1,"Actual native section insertion retires durable result before onCreated/visibility; same actor reentry cannot consume another compound");h.succeed();}
 @GameTest public void lateNativeCallbackErrorDoesNotRestoreAcceptedResultOrPaidSource(GameTestHelper h){var source=source(h,3,10);var observation=new LegacyMaterialTestFixtures.Observation();boolean caught=false;try{LegacyMaterialTestFixtures.with(h.getLevel(),source,null,LegacyMaterialTestFixtures.Mode.EARLY_THROW,observation,source::tick);}catch(LegacyMaterialTestFixtures.NativeFault actual){caught=actual==observation.fault;}h.assertTrue(caught&&observation.exactInsertion&&source.getItem().getCount()==2&&observation.saved.getListOrEmpty("Pending").isEmpty()&&LegacyMaterialTestFixtures.capture(h.getLevel()).getListOrEmpty("Pending").isEmpty(),"Exact native failure after real section acceptance propagates without recreating durable result claim or consumed input");h.succeed();}
 @GameTest public void placedLightRefusalPaysOneChargedPartAndStillAttemptsNativeDestroy(GameTestHelper h){var pos=h.absolutePos(LIGHT);h.getLevel().setBlockAndUpdate(pos,Blocks.GLOWSTONE.defaultBlockState());var source=source(h,2,0);var input=source.getItem();var observation=new LegacyMaterialTestFixtures.Observation();boolean[] consumed={false};LegacyMaterialTestFixtures.with(h.getLevel(),source,pos,LegacyMaterialTestFixtures.Mode.REFUSE,observation,()->consumed[0]=AllItems.CHROMATIC_COMPOUND.checkLight(input,source,h.getLevel(),input,source.position(),pos,h.getLevel().getBlockState(pos)));h.assertTrue(consumed[0]&&observation.destroys==1&&observation.sourceAtDestroy==1&&source.getItem().getCount()==1&&h.getLevel().getBlockState(pos).isAir()&&LegacyMaterialTestFixtures.owned(h.getLevel(),AllItems.CHROMATIC_COMPOUND)==1,"Source charged split is paid/durable even native add false; later exact native destroy(false) still runs");var endpoint=observation.endpoint;LegacyMaterialTestFixtures.retry(h.getLevel());h.assertTrue(h.getLevel().getEntity(endpoint.getUUID())==endpoint&&AllItems.CHROMATIC_COMPOUND.getLight(endpoint.getItem())==1,"Retry preserves exact charged actual payload");h.succeed();}
 @GameTest public void nativeDestroyFalseDoesNotRefundOrGateOpticalLightProvider(GameTestHelper h){var pos=h.absolutePos(LIGHT);h.getLevel().setBlockAndUpdate(pos,Blocks.GLOWSTONE.defaultBlockState());var source=source(h,2,0);var observation=new LegacyMaterialTestFixtures.Observation();LegacyMaterialTestFixtures.with(h.getLevel(),source,pos,LegacyMaterialTestFixtures.Mode.DESTROY_FALSE,observation,()->{var stack=source.getItem();h.assertTrue(AllItems.CHROMATIC_COMPOUND.checkLight(stack,source,h.getLevel(),stack,source.position(),pos,h.getLevel().getBlockState(pos)),"Source optical provider qualifies");});h.assertTrue(observation.destroys==1&&observation.sourceAtDestroy==1&&h.getLevel().getBlockState(pos).is(Blocks.GLOWSTONE)&&nearby(h,AllItems.CHROMATIC_COMPOUND).stream().filter(entity->AllItems.CHROMATIC_COMPOUND.getLight(entity.getItem())==1).count()==1,"Source ignores false destroy result after actual compound debit/output publication");h.succeed();}
 @GameTest public void actualLavaColliderMissRemainsARepeatableOpticalProvider(GameTestHelper h){var pos=h.absolutePos(LIGHT);h.getLevel().setBlockAndUpdate(pos,Blocks.LAVA.defaultBlockState());var source=source(h,3,0);for(int i=0;i<2;i++){var input=source.getItem();h.assertTrue(AllItems.CHROMATIC_COMPOUND.checkLight(input,source,h.getLevel(),input,source.position(),pos,h.getLevel().getBlockState(pos)),"Genuine COLLIDER/NONE clip final MISS block position qualifies source Lava");}h.assertTrue(source.getItem().getCount()==1&&h.getLevel().getBlockState(pos).is(Blocks.LAVA)&&nearby(h,AllItems.CHROMATIC_COMPOUND).stream().filter(entity->AllItems.CHROMATIC_COMPOUND.getLight(entity.getItem())==1).mapToInt(entity->entity.getItem().getCount()).sum()==2,"Two finite compound debits, two charged outputs, native destroy no-op leaves repeatable Lava exactly as source");h.succeed();}
 @GameTest public void nativeDestroyThrowHappensAfterChargedOutputAndDoesNotRefund(GameTestHelper h){var pos=h.absolutePos(LIGHT);h.getLevel().setBlockAndUpdate(pos,Blocks.GLOWSTONE.defaultBlockState());var source=source(h,2,0);var observation=new LegacyMaterialTestFixtures.Observation();boolean caught=false;try{LegacyMaterialTestFixtures.with(h.getLevel(),source,pos,LegacyMaterialTestFixtures.Mode.DESTROY_THROW,observation,()->{var input=source.getItem();AllItems.CHROMATIC_COMPOUND.checkLight(input,source,h.getLevel(),input,source.position(),pos,h.getLevel().getBlockState(pos));});}catch(LegacyMaterialTestFixtures.NativeFault actual){caught=actual==observation.fault;}h.assertTrue(caught&&observation.destroys==1&&source.getItem().getCount()==1&&h.getLevel().getBlockState(pos).is(Blocks.GLOWSTONE)&&nearby(h,AllItems.CHROMATIC_COMPOUND).stream().filter(entity->AllItems.CHROMATIC_COMPOUND.getLight(entity.getItem())==1).count()==1,"Exact later native destroy error propagates after real paid output; no source refund or inferred block payment");h.succeed();}
}
